def test_linear_regression_multi_pheno_same(self):
    covariates = hl.import_table(resource('regressionLinear.cov'), key='Sample', types={'Cov1': hl.tfloat, 'Cov2': hl.tfloat})
    pheno = hl.import_table(resource('regressionLinear.pheno'), key='Sample', missing='0', types={'Pheno': hl.tfloat})
    mt = hl.import_vcf(resource('regressionLinear.vcf'))
    for linreg_function in self.linreg_functions:
        single = linreg_function(y=pheno[mt.s].Pheno, x=mt.GT.n_alt_alleles(), covariates=list(covariates[mt.s].values()))
        multi = linreg_function(y=[pheno[mt.s].Pheno, pheno[mt.s].Pheno], x=mt.GT.n_alt_alleles(), covariates=list(covariates[mt.s].values()))

        def eq(x1, x2):
            return hl.is_nan(x1) & hl.is_nan(x2) | (hl.abs(x1 - x2) < 0.0001)
        combined = single.annotate(multi=multi[single.key])
        self.assertTrue(combined.aggregate(hl.agg.all(eq(combined.p_value, combined.multi.p_value[0]) & eq(combined.multi.p_value[0], combined.multi.p_value[1]))))

def test_logistic_regression_rows_max_iter_zero(self):
    import hail as hl
    mt = hl.utils.range_matrix_table(1, 3)
    mt = mt.annotate_entries(x=hl.literal([1, 1, 10]))
    try:
        ht = hl.logistic_regression_rows(test='wald', y=hl.literal([0, 0, 1])[mt.col_idx], x=mt.x[mt.col_idx], covariates=[1], max_iterations=0)
        ht.globals.collect()
    except Exception as exc:
        assert 'Failed to fit logistic regression null model (standard MLE with covariates only): Newton iteration failed to converge' in exc.args[0]
    else:
        assert False

