def test_warn_if_no_intercept(self):
    mt = hl.balding_nichols_model(1, 1, 1).add_row_index().add_col_index()
    intercept = hl.float64(1.0)
    for covariates in [[], [mt.row_idx], [mt.col_idx], [mt.GT.n_alt_alleles()], [mt.row_idx, mt.col_idx, mt.GT.n_alt_alleles()]]:
        self.assertTrue(hl.methods.statgen._warn_if_no_intercept('', covariates))
        self.assertFalse(hl.methods.statgen._warn_if_no_intercept('', [intercept, *covariates]))

def test_gq_from_pl_missing():
    result = hl.eval(hl.gq_from_pl([450, None, 73, 85, 0, None]))
    assert result == 73

def test_gq_from_pl_all_missing():
    result = hl.eval(hl.gq_from_pl(hl.literal([None, None, None], hl.tarray(hl.tint32))))
    assert result == 0
